SELECT ticket_id, status
FROM support_tickets
WHERE payload ->> 'channel' = 'chat';

SELECT invoice_id, MAX(attempted_at) AS latest_dunning_attempt_at
FROM dunning_attempts
GROUP BY invoice_id;

SELECT alert_id
FROM alerts
WHERE status = 'open';

SELECT customer_id, COUNT(alert_id) FILTER (WHERE status = 'open') AS open_alerts
FROM alerts
GROUP BY customer_id;

SELECT transaction_id
FROM transactions
WHERE (payload #>> '{risk_score}')::NUMERIC >= 80;
